import unittest

from solucao import pares
from solucao import pares_ordenados


class TestChaveEValorJuntos(unittest.TestCase):
    def test_pares_devolve_os_pares(self):
        """pares devolve um par por chave e valor"""
        self.assertEqual(sorted(pares({"a": 1, "b": 2})), [("a", 1), ("b", 2)])

    def test_pares_ordenados_por_chave(self):
        """pares_ordenados devolve os pares em ordem de chave"""
        self.assertEqual(pares_ordenados({"b": 2, "a": 1}), [("a", 1), ("b", 2)])

    def test_pares_ordenados_de_outro_dicionario(self):
        """pares_ordenados funciona com outro dicionario"""
        self.assertEqual(
            pares_ordenados({"uva": 6, "pao": 4, "abacate": 3}),
            [("abacate", 3), ("pao", 4), ("uva", 6)],
        )

